{
  "name": "customer-support-stack",
  "private": true,
  "scripts": {
    "start": "concurrently --kill-others-on-fail --names backend,frontend \"npm run backend\" \"npm run frontend\"",
    "frontend": "npm --prefix frontend install && npm --prefix frontend run dev",
    "backend": "./scripts/run-backend.sh"
  },
  "devDependencies": {
    "concurrently": "^9.1.2"
  }
}

